function getColorEcorregiones(NOMBRE_ECO) {
    switch (NOMBRE_ECO) {
        case 'Altos Andes':
            return { color: "#FFFFCC" };
        case 'Puna':
            return { color: "#C0C0C0" };
        case 'Monte de Llanuras y Mesetas':
            return { color: "#EEDD82" };
        case 'Estepa Patagonica':
            return { color: "#DAA520" };
        case 'Monte de Sierras y Bolsones':
            return { color: "#A52A2A" };
        case 'Chaco Seco':
            return { color: "#D2691E" };
        case 'Espinal':
            return { color: "#A0522D" };
        case 'Pampa':
            return { color: "#F4A460" };
        case 'Chaco Humedo':
            return { color: "#9ACD32" };
        case 'Campos y Malezales':
            return { color: "#ADFF2F" };
        case 'Bosque Patagonicos':
            return { color: "#6B8E23" };
        case 'Selva Paranense':
            return { color: "#228B22" };
        case 'Selva de las Yungas':
            return { color: "#006400" };
        case 'Esteros del Ibera':
            return { color: "#556B2F" };
        case 'Delta e Islas del Parana':
            return {color: '#c39b4f' };
        default:
            return { color: "#000000" }; // Color por defecto si no hay coincidencia
    }
}


function styleEco(feature) {
    const { color } = getColorEcorregiones(feature.properties.NOMBRE_ECO);
    return {
      color: color,
      weight: 2,
      opacity: 0.9,
      dashArray: "0",
      fillOpacity: 0.9,
    };
  }

// Contenido del popup para cada feature
function popupContentEcoregion(feature) {
  return (
      "<div id='Estilo1'><h3>Descripción</h3></div>" +
      "<hr class='hrx' style='color: #ef7d26;' align='left' noshade='noshade' size='0.5' width='100%' />" +
      "<div id='Estilo3a'>" +
      "<b> Nombre : </b>" + feature.properties.NOMBRE_ECO + "<br>" +
    //   "<b> Tipo de Suelo : </b>" + feature.properties.TIPO_UC + "<br>" +
    //     "<br>" +
    //     "<b> Nombre de Suelo : </b>" + feature.properties.ORDEN_SUE1 + "<br>" +
    //     "<br>" +
      "</div>"
  );
}
// leyenda


// Función para generar la leyenda
function createLegendEcorregiones() {
    var legend = L.control({ position: 'bottomright' });

    legend.onAdd = function () {
        var div = L.DomUtil.create('div', 'info legend');
        var labels = [];
        var styles = [
           
            { label: 'Chaco Seco', color: '#D2691E' },
            { label: 'Espinal', color: '#A0522D' },
            //{ label: 'Pampa', color: '#F4A460' },
            { label: 'Chaco Humedo', color: '#9ACD32' },
            { label: 'Campos y Malezales', color: '#ADFF2F' },
           // { label: 'Bosque Patagonicos', color: '#6B8E23' },
            { label: 'Selva Paranaense', color: '#228B22' },
           // { label: 'Selva de las Yungas', color: '#006400' },
            { label: 'Esteros del Ibera', color: '#556B2F' },
            { label: 'Delta e Islas del Parana', color: '#c39b4f' },

        ];
        // Genera el contenido HTML de la leyenda
        styles.forEach(function (style) {
            labels.push(
                '<i style="background:' + style.color + '"></i> ' + style.label
            );
        });

        div.innerHTML = labels.join('<br>');
        return div;
    };

    // Función para mostrar/ocultar la leyenda
    function toggleLegend() {
        if (map.hasLayer(Ecoregion)) {
            legend.addTo(map);
        } else {
            legend.remove();
        }
    }
// Eliminar la leyenda al inicio
legend.remove();
    // Escucha el cambio de estado de la capa
    map.on('overlayadd overlayremove', toggleLegend);
}



